import { EMPTY_OBJ, EMPTY_ARR, IS_NON_DIMENSIONAL } from '../constants';
import { assign, removeNode } from '../util';
import options from '../options';

/**
 * Coordinates child reconciliation, property application, component
 * scheduling, vnode construction, and host tree commits.
 */
class TreeCoordinator {
	constructor() {
		this._childWork = {
			empty: EMPTY_ARR,
			emptyProps: EMPTY_OBJ,
			fragmentType: null,
			depthStep: 1
		};
		this._propWork = {
			nonDimensional: IS_NON_DIMENSIONAL,
			styleClear: '',
			xlinkNS: 'http://www.w3.org/1999/xlink',
			oldSkip: { children: 1, key: 1 },
			newSkip: { children: 1, key: 1, value: 1, checked: 1 },
			eventProxy: null,
			eventProxyCapture: null
		};
		this._scheduleWork = {
			queue: [],
			count: 0,
			prevDebounce: undefined,
			defer:
				typeof Promise == 'function'
					? Promise.prototype.then.bind(Promise.resolve())
					: setTimeout,
			siblingSearch: null,
			pointerTarget: null
		};
		this._vnodeWork = { options: options };
		this._unmountWork = { errorOwner: null, removeNode: removeNode };
		this._hostWork = {
			assign: assign,
			hydrateSentinel: EMPTY_OBJ,
			svgNS: 'http://www.w3.org/2000/svg',
			componentCtor: null
		};
	}

	diffChildren(
		parentDom,
		renderResult,
		newParentVNode,
		oldParentVNode,
		globalContext,
		isSvg,
		excessDomChildren,
		commitQueue,
		oldDom,
		isHydrating
	) {
		let i, j, oldVNode, childVNode, newDom, firstChildDom, refs;
		let oldChildren =
			(oldParentVNode && oldParentVNode._children) || this._childWork.empty;
		let oldChildrenLength = oldChildren.length;

		oldDom = this.resolveOldDom(
			oldDom,
			excessDomChildren,
			oldChildrenLength,
			oldParentVNode
		);

		newParentVNode._children = [];
		for (i = 0; i < renderResult.length; i++) {
			childVNode = this.coerceChildVNode(
				renderResult[i],
				newParentVNode,
				i
			);

			if (childVNode == null) {
				continue;
			}

			childVNode._parent = newParentVNode;
			childVNode._depth = newParentVNode._depth + this._childWork.depthStep;

			oldVNode = this.matchOldChild(
				childVNode,
				oldChildren,
				i,
				oldChildrenLength
			);

			this.diff(
				parentDom,
				childVNode,
				oldVNode,
				globalContext,
				isSvg,
				excessDomChildren,
				commitQueue,
				oldDom,
				isHydrating
			);

			newDom = childVNode._dom;
			refs = this.recordChildRef(childVNode, oldVNode, newDom, refs);

			if (newDom != null) {
				if (firstChildDom == null) {
					firstChildDom = newDom;
				}

				oldDom = this.arrangeChildDom(
					childVNode,
					oldVNode,
					oldChildren,
					excessDomChildren,
					newDom,
					oldDom,
					parentDom
				);

				this.markParentResumeDom(
					newParentVNode,
					parentDom,
					oldDom,
					isHydrating
				);
			} else if (
				oldDom &&
				oldVNode._dom == oldDom &&
				oldDom.parentNode != parentDom
			) {
				oldDom = this.getDomSibling(oldVNode);
			}
		}

		newParentVNode._dom = firstChildDom;
		this.dropExcessDomChildren(newParentVNode, excessDomChildren);
		this.dropStaleVNodes(
			newParentVNode,
			oldParentVNode,
			oldChildren,
			oldChildrenLength
		);
		this.flushRefUpdates(refs);
	}

	resolveOldDom(oldDom, excessDomChildren, oldChildrenLength, oldParentVNode) {
		if (oldDom == this._childWork.emptyProps) {
			if (excessDomChildren != null) {
				oldDom = excessDomChildren[0];
			} else if (oldChildrenLength) {
				oldDom = this.getDomSibling(oldParentVNode, 0);
			} else {
