	}

	recordChildRef(childVNode, oldVNode, newDom, refs) {
		let j;
		if ((j = childVNode.ref) && oldVNode.ref != j) {
			if (!refs) refs = [];
			if (oldVNode !== this._childWork.emptyProps && oldVNode.ref) {
				refs.push(oldVNode.ref, null, childVNode);
			}
			refs.push(j, childVNode._component || newDom, childVNode);
		}
		return refs;
	}

	arrangeChildDom(
		childVNode,
		oldVNode,
		oldChildren,
		excessDomChildren,
		newDom,
		oldDom,
		parentDom
	) {
		if (oldChildren == null) {
			oldChildren = this._childWork.empty;
		}
		if (
			typeof childVNode.type == 'function' &&
			childVNode._children === oldVNode._children
