		let i;
		let oldSkip = this._propWork.oldSkip;
		let newSkip = this._propWork.newSkip;

		for (i in oldProps) {
			if (!(i in oldSkip) && !(i in newProps)) {
				this.setProperty(dom, i, null, oldProps[i], isSvg);
			}
		}

		for (i in newProps) {
			if (
				(!hydrate || typeof newProps[i] == 'function') &&
